CREATE TABLE users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text NOT NULL UNIQUE, display_name text NOT NULL, password_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE user_roles (user_id uuid NOT NULL REFERENCES users(id), role text NOT NULL CHECK(role IN ('customer','organizer','admin')), PRIMARY KEY(user_id,role));
CREATE TABLE refresh_sessions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), token_hash text NOT NULL UNIQUE, family uuid NOT NULL, expires_at timestamptz NOT NULL, rotated_at timestamptz, revoked_at timestamptz);
CREATE INDEX refresh_family ON refresh_sessions(family);
CREATE TABLE venues (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, address text NOT NULL, city text NOT NULL, country text NOT NULL, capacity integer NOT NULL CHECK(capacity>0), timezone text NOT NULL, archived_at timestamptz);
CREATE TABLE events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_id uuid NOT NULL REFERENCES users(id), venue_id uuid NOT NULL REFERENCES venues(id), title text NOT NULL, description text NOT NULL, category_label text NOT NULL, starts_at timestamptz NOT NULL, ends_at timestamptz NOT NULL, sales_open_at timestamptz NOT NULL, sales_close_at timestamptz NOT NULL, timezone text NOT NULL, capacity integer NOT NULL CHECK(capacity>0), currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), state text NOT NULL DEFAULT 'DRAFT' CHECK(state IN ('DRAFT','PUBLISHED','CANCELED','COMPLETED')), version integer NOT NULL DEFAULT 1, CHECK(sales_open_at<sales_close_at AND sales_close_at<=starts_at AND starts_at<ends_at));
CREATE INDEX event_discovery ON events(starts_at,id) WHERE state='PUBLISHED';
CREATE INDEX event_owner ON events(owner_id,id);
CREATE INDEX venue_city ON venues(lower(city));
CREATE TABLE ticket_categories (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL REFERENCES events(id), name text NOT NULL, capacity integer NOT NULL CHECK(capacity>=0), price_minor integer NOT NULL CHECK(price_minor>=0 AND price_minor<=100000000), currency text NOT NULL CHECK(currency ~ '^[A-Z]{3}$'), reserved_count integer NOT NULL DEFAULT 0 CHECK(reserved_count>=0), sold_count integer NOT NULL DEFAULT 0 CHECK(sold_count>=0), CHECK(reserved_count+sold_count<=capacity));
CREATE INDEX category_event ON ticket_categories(event_id);
CREATE TABLE bookings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), customer_id uuid NOT NULL REFERENCES users(id), event_id uuid NOT NULL REFERENCES events(id), category_id uuid NOT NULL REFERENCES ticket_categories(id), quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 6), unit_price_minor integer NOT NULL CHECK(unit_price_minor>=0), total_minor integer NOT NULL CHECK(total_minor=quantity*unit_price_minor), currency text NOT NULL, category_name text NOT NULL, event_title text NOT NULL, state text NOT NULL CHECK(state IN ('RESERVED','CONFIRMED','EXPIRED','CANCELED','REFUND_PENDING','REFUNDED')), expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX booking_customer ON bookings(customer_id,created_at DESC);
CREATE INDEX booking_expiry ON bookings(expires_at) WHERE state='RESERVED';
CREATE INDEX booking_event ON bookings(event_id,state);
CREATE TABLE payment_attempts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), provider text NOT NULL CHECK(provider IN ('simulator','stripe_test')), operation_key text NOT NULL UNIQUE, provider_session_id text UNIQUE, provider_payment_id text UNIQUE, checkout_url text, amount_minor integer NOT NULL CHECK(amount_minor>=0), currency text NOT NULL, state text NOT NULL DEFAULT 'CREATED' CHECK(state IN ('CREATED','PENDING','SUCCEEDED','FAILED','CANCELED')), reconciliation_required boolean NOT NULL DEFAULT false, manual_resolution boolean NOT NULL DEFAULT false, lease_until timestamptz, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), updated_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE UNIQUE INDEX unresolved_payment ON payment_attempts(booking_id) WHERE state IN ('CREATED','PENDING');
CREATE TABLE refunds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), payment_id uuid NOT NULL REFERENCES payment_attempts(id), booking_id uuid REFERENCES bookings(id), operation_key text NOT NULL UNIQUE, provider_refund_id text UNIQUE, amount_minor integer NOT NULL CHECK(amount_minor>=0), reason text NOT NULL CHECK(reason IN ('customer','event_canceled','late_payment','extra_payment')), state text NOT NULL DEFAULT 'REQUESTED' CHECK(state IN ('REQUESTED','PROCESSING','SUCCEEDED','FAILED')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, next_at timestamptz NOT NULL DEFAULT clock_timestamp(), manual_resolution boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(payment_id,reason));
CREATE TABLE tickets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), booking_id uuid NOT NULL REFERENCES bookings(id), ordinal integer NOT NULL CHECK(ordinal>0), state text NOT NULL DEFAULT 'VALID' CHECK(state IN ('VALID','CHECKED_IN','SUSPENDED','VOID')), token_hash text NOT NULL UNIQUE, token_encrypted text NOT NULL, qr_svg text, artifact_status text NOT NULL DEFAULT 'PENDING' CHECK(artifact_status IN ('PENDING','READY','FAILED')), checked_in_at timestamptz, checked_in_by uuid REFERENCES users(id), UNIQUE(booking_id,ordinal), CHECK((state='CHECKED_IN')=(checked_in_at IS NOT NULL)));
CREATE TABLE webhook_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), provider text NOT NULL, event_id text NOT NULL, payload jsonb NOT NULL, state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','PROCESSING','DONE','DEAD')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, next_at timestamptz NOT NULL DEFAULT clock_timestamp(), error_code text, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), UNIQUE(provider,event_id));
CREATE INDEX webhook_pending ON webhook_events(next_at) WHERE state IN ('PENDING','PROCESSING');
CREATE TABLE outbox_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_type text NOT NULL, schema_version integer NOT NULL DEFAULT 1, aggregate_id uuid NOT NULL, correlation_id text NOT NULL, payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), published_at timestamptz, lease_until timestamptz, attempts integer NOT NULL DEFAULT 0, next_at timestamptz NOT NULL DEFAULT clock_timestamp(), dead boolean NOT NULL DEFAULT false);
CREATE INDEX outbox_pending ON outbox_events(next_at) WHERE published_at IS NULL AND NOT dead;
CREATE TABLE processed_messages (consumer_name text NOT NULL,event_id uuid NOT NULL,completed_at timestamptz NOT NULL DEFAULT clock_timestamp(), PRIMARY KEY(consumer_name,event_id));
CREATE TABLE notification_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), business_key text NOT NULL UNIQUE, booking_id uuid NOT NULL REFERENCES bookings(id), kind text NOT NULL CHECK(kind IN ('confirmation','refund')), state text NOT NULL DEFAULT 'PENDING' CHECK(state IN ('PENDING','PROCESSING','DONE','DEAD')), attempts integer NOT NULL DEFAULT 0, lease_until timestamptz, next_at timestamptz NOT NULL DEFAULT clock_timestamp(), error_code text);
CREATE TABLE idempotency_requests (actor_id uuid NOT NULL REFERENCES users(id), operation text NOT NULL, key text NOT NULL, request_hash text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp(), expires_at timestamptz NOT NULL DEFAULT clock_timestamp()+interval '7 days',PRIMARY KEY(actor_id,operation,key));
CREATE TABLE audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid REFERENCES users(id), action text NOT NULL, resource_id uuid NOT NULL, correlation_id text NOT NULL, metadata jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE demo_sessions (id uuid PRIMARY KEY, attempt_id uuid NOT NULL UNIQUE REFERENCES payment_attempts(id), outcome text CHECK(outcome IN ('success','decline')), completion_key text, completed_at timestamptz);
CREATE TABLE simulator_operations (operation_key text PRIMARY KEY, kind text NOT NULL, result jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE TABLE catalog_generation (id integer PRIMARY KEY CHECK(id=1), generation bigint NOT NULL DEFAULT 1);
INSERT INTO catalog_generation(id) VALUES(1);
CREATE TABLE dead_letters (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), event_id uuid NOT NULL, envelope jsonb NOT NULL, error_code text NOT NULL, replayed_at timestamptz, created_at timestamptz NOT NULL DEFAULT clock_timestamp());
CREATE INDEX refund_pending ON refunds(next_at) WHERE state IN ('REQUESTED','PROCESSING');
CREATE INDEX notification_pending ON notification_jobs(next_at) WHERE state IN ('PENDING','PROCESSING');
